def _unwrap(t):
    return ''.join(t.split())

def _uncaesar(t, sh=7):
    out = []
    for ch in t:
        o = ord(ch)
        if 65 <= o <= 90:
            out.append(chr((o - 65 - sh) % 26 + 65))
        elif 97 <= o <= 122:
            out.append(chr((o - 97 - sh) % 26 + 97))
        else:
            out.append(ch)
    return ''.join(out)

def _unb64(t):
    if sys.version_info[0] == 3 and isinstance(t, str):
        t = t.encode('ascii')
    pad = len(t) % 4
    if pad:
        t = t + b'=' * (4 - pad)
    return base64.urlsafe_b64decode(t)

def _decode():
    s = _unwrap(ENC)
    s = s[::-1]
    s = _uncaesar(s)
    d = _unb64(s)
    d = zlib.decompress(d)
    return d

if __name__ == '__main__':
    _data = _decode()
    if sys.version_info[0] == 3:
        _data = _data.decode('utf-8')
    exec(_data, {'__name__': '__main__', '__file__': __file__})
